"""Small, original worked examples for the DSA video lessons.

Every entry supplies changing *data*, not just a rotating highlight. The four
beats are shown after the introduction, with the last result held for review.
The renderer turns these states into animated diagrams.
"""


def case(kind, initial, *beats, aux=None, edges=None):
    # beat: (values, active indices, completed indices, short observation)
    return {"kind": kind, "initial": initial, "beats": beats, "aux": aux or [], "edges": edges or []}


