def validate(ids):
    missing = set(ids) - set(STORIES)
    extra = set(STORIES) - set(ids)
    if missing or extra:
        raise ValueError(f"Storyboard mismatch: missing={sorted(missing)}, extra={sorted(extra)}")
    for id, story in STORIES.items():
        if len(story["beats"]) != 4 or len({repr(beat) for beat in story["beats"]}) < 3:
            raise ValueError(f"Storyboard has too few distinct states: {id}")
        if any(len(beat) != 4 for beat in story["beats"]):
            raise ValueError(f"Storyboard beat needs values, active, complete and note: {id}")
